package ir.sejadalmas.salesagent;
import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;
public class Api{
 private final String base,token; Api(String b,String t){base=normalize(b);token=t==null?"":t;} static String normalize(String s){s=s==null?"":s.trim();if(!s.matches("(?i)^https?://.*"))s="https://"+s;return s.replaceAll("/+$","");}
 JSONObject health()throws Exception{return call("health","GET",null);} JSONObject call(String path,String method,JSONObject body)throws Exception{String[] roots={base+"/sales-mobile-api/",base+"/sales_mobile_api/api/",base+"/index.php/sales_mobile_api/api/"};StringBuilder errs=new StringBuilder();for(String root:roots){try{return request(root+path,method,body);}catch(Exception e){if(errs.length()>0)errs.append(" | ");errs.append(e.getMessage());}}throw new Exception("سرویس موبایل در دسترس نیست");}
 private JSONObject request(String url,String method,JSONObject body)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);c.setRequestMethod(method);c.setRequestProperty("Accept","application/json");c.setRequestProperty("Content-Type","application/json; charset=utf-8");c.setRequestProperty("X-Requested-With","XMLHttpRequest");if(!token.isEmpty())c.setRequestProperty("Authorization","Bearer "+token);if(body!=null){c.setDoOutput(true);try(OutputStream o=c.getOutputStream()){o.write(body.toString().getBytes(StandardCharsets.UTF_8));}}int code=c.getResponseCode();InputStream in=code>=400?c.getErrorStream():c.getInputStream();StringBuilder s=new StringBuilder();if(in!=null)try(BufferedReader r=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8))){String x;while((x=r.readLine())!=null)s.append(x);}String raw=s.toString().trim();if(code>=300&&code<400)throw new Exception("redirect "+code);if(raw.isEmpty())throw new Exception("empty "+code);if(raw.startsWith("<")||raw.toLowerCase().contains("<!doctype"))throw new Exception("html "+code);try{return new JSONObject(raw);}catch(JSONException e){throw new Exception("json "+code);}}
}
